    jgObj_lampara: 'Lampe', jgObj_regadera: 'Gießkanne', jgObj_nutrientes: 'Nährstoffflasche',
    jgObj_termometro: 'Thermometer und Heizung', jgObj_humidificador: 'Luftbefeuchter',
